/** Premultiplied 16x16 RGBA recovered from Linux 8.3.27 native mattes. */
const pictures = Object.freeze({
  "MoveUp": "",
  "MoveDown": "",
  "CloneListItem": "",
  "CloneObject": "",
  "Find": "",
  "SearchControl": "",
  "Refresh": "",
  "Post": "",
  "EventLog": "",
  "CheckAll": "",
  "UncheckAll": "",
  "DeleteListItemDirectly": "",
  "ExchangePlan": "",
  "PostAndClose": "",
  "Write": "",
  "MarkObjectForDeletion": "",
  "UndoPosting": "",
  "ShowInList": "",
  "ChangeHistory": "",
  "CustomizeForm": "",
  "Help": "",
  "Create": "",
  "Change": "",
  "CancelSearch": "",
  "GetCurrentRowURL": "",
  "ListSettings": "",
  "SelectSettings": "",
  "SaveSettings": "",
  "OutputList": "",
  "SetPeriod": "",
  "DeleteListItem": "",
  "CreateFolder": "",
  "ViewMode": "",
  "MoveItem": "",
  "LevelDown": "",
  "LevelUp": "",
  "HierarchicalList": "",
  "List": "",
  "Tree": "",
});

const tableMenuPictures = Object.freeze({
  "MarkObjectForDeletion": "",
  "DeleteListItemDirectly": "",
  "Refresh": "",
  "Find": "",
  "Post": "",
});

export function standardPicture(name, variant = 'standard') {
  if (!['standard', 'tableMenu'].includes(variant) || typeof name !== 'string') return undefined;
  const key = name.replace(/^StdPicture\./, '');
  const encoded = variant === 'tableMenu' ? tableMenuPictures[key] ?? pictures[key] : pictures[key];
  if (!encoded) return undefined;
  const rgba = new Uint8ClampedArray(encoded.length / 2);
  for (let i = 0; i < rgba.length; i += 4) {
    const alpha = parseInt(encoded.slice((i + 3) * 2, (i + 4) * 2), 16);
    rgba[i + 3] = alpha;
    for (let channel = 0; channel < 3; channel++) {
      const premultiplied = parseInt(encoded.slice((i + channel) * 2, (i + channel + 1) * 2), 16);
      rgba[i + channel] = alpha ? Math.round(premultiplied * 255 / alpha) : 0;
    }
  }
  return { width: 16, height: 16, rgba, ...(key === 'GetCurrentRowURL' ? { isTemplate: true } : {}) };
}
